public IList<IList<int>> CombinationSum(int[] candidates, int target)
{
    var result = new List<IList<int>>();
    Array.Sort(candidates);              // enables pruning
    var current = new List<int>();

    void Dfs(int start, int remaining)
    {
        if (remaining == 0) { result.Add(new List<int>(current)); return; }
        for (int i = start; i < candidates.Length; i++)
        {
            if (candidates[i] > remaining) break;   // sorted: nothing later fits
            current.Add(candidates[i]);             // choose
            Dfs(i, remaining - candidates[i]);      // i (not i+1): reuse allowed
            current.RemoveAt(current.Count - 1);     // un-choose (backtrack)
        }
    }

    Dfs(0, target);
    return result;
}
